<style>
    .citeck-widget-contacts .form-group {
        margin: 0;
    }

    /* The platform sets a border and 0.65rem/0.5rem padding on every datagrid cell. Here each
       cell holds a whole contact card, so the cell must not add any frame of its own. The
       selector has to stay inside .citeck-widget-contacts and outrank
       `.formio-component-datagrid table.table-bordered td`, otherwise it either leaks onto
       every table of the page or loses and does nothing. */
    .citeck-widget-contacts .formio-component-datagrid table.table-bordered th,
    .citeck-widget-contacts .formio-component-datagrid table.table-bordered td {
        padding: 0 0 16px;
        border: none;
        height: auto;
    }

    /* The gap belongs between the cards, not after the last one - otherwise a widget of
       collapsed cards ends with an empty strip as tall as a card. */
    .citeck-widget-contacts .formio-component-datagrid table.table-bordered tr:last-child > td {
        padding-bottom: 0;
    }

    /* Direct child, not descendant: a contact card sits inside a wrapper panel, so a descendant
       selector applied this inset twice and squeezed the content into the middle of the widget.
       The card adds no inset of its own, so the fields line up with the neighbouring
       dashlets, which rely on the dashlet padding alone. */
    /* The step below the title belongs to the body, not to the title: a collapsed body is
       display:none, so its margin disappears with it and collapsed cards do not reserve room
       for content they are not showing. */
    .citeck-widget-contacts .card > .card-header {
        padding-bottom: 0;
    }

    .citeck-widget-contacts .card > .card-body.panel-body {
        padding: 0 !important;
        margin-top: 11px;
        margin-bottom: 0;
        /* the rows carry their own 5px above and below; the platform puts a 1rem flex gap on a
           datagrid panel body, which pushed the comment 16px away while the fields sat 10px
           apart - !important because that rule outranks this one */
        gap: 0 !important;
    }

    .citeck-widget-contacts-comment_view-mode,
    .citeck-widget-contacts-columns dl {
        border-bottom: none !important;
        padding: 5px 0 !important;
    }

    .citeck-widget-contacts-comment_view-mode dd,
    .citeck-widget-contacts-columns dd {
        color: #444444;
        font-weight: 600;
    }

    .citeck-widget-contacts-comment_view-mode dt,
    .citeck-widget-contacts-columns dt {
        color: #B7B7B7;
    }
    .citeck-widget-contacts-comment_view-mode dt:after,
    .citeck-widget-contacts-columns dt:after {
        content: ":";
    }

    /* Keep the platform's title chip (`.formio-form .card .card-title`) - with several contacts
       in one widget it is the only thing separating one card from the next. Only the vertical
       rhythm and the icon alignment are adjusted here. */
    .citeck-widget-contacts .card .card-title {
        margin-top: 2px;
        margin-bottom: 0 !important;
        margin-left: 0;
        font-size: 14px !important;

        display: flex;
        gap: 3px;
        align-items: center;
    }
</style>

